    private static String homePage(){return layout("CINEHUB", "<section class='entry-header entry-header-style-2' style=\"background-image:linear-gradient(90deg,rgba(0,0,0,.76),rgba(0,0,0,.42),rgba(0,0,0,.22)),url('/static/assets/imgs/cinehub-hero-theater.png')!important\"><div class='container entry-header-content'><h1>오늘, 어떤 영화를 볼까요?</h1><h2>장르와 분위기를 알려주면 CINEHUB가 당신에게 어울리는 한 편을 찾아드려요.</h2></div></section><div class='container'><div class='hot-tags'><div class='widget-header-3'><h5 class='widget-title'>실시간 인기 영화 TOP 5</h5></div><div id='movieResults'><p class='muted'>인기 영화를 불러오는 중입니다.</p></div></div><div class='loop-grid'><div class='widget-header-3'><h5 class='widget-title'>커뮤니티 실시간 인기글</h5></div><div id='posts'><p class='muted'>게시글을 불러오는 중입니다.</p></div></div></div>", "loadPopularMovies();loadPosts('posts',5);");}
    private static String postsPage(){return layout("게시글 | CINEHUB", "<div class='container'><div class='widget-header-3'><h1 class='widget-title'>전체 게시글</h1></div><div id='posts'><p class='muted'>게시글을 불러오는 중입니다.</p></div><nav class='pagination' id='postPagination'></nav></div>", "fetch('/api/posts').then(r=>r.json()).then(d=>{let a=d.posts||[],page=1,draw=()=>{let pages=Math.max(1,Math.ceil(a.length/10));document.getElementById('posts').innerHTML=a.slice((page-1)*10,page*10).map(p=>'<a class=\\\"post-card\\\" href=\\\"/post/'+p.id+'\\\"><h3>'+safe(p.title)+'</h3><p>'+safe(p.content).slice(0,140)+'</p><small>'+safe(p.author)+' · '+safe(p.createdAt)+'</small></a>').join('')||'<p>게시글이 없습니다.</p>';document.getElementById('postPagination').innerHTML=Array.from({length:pages},(_,i)=>'<button class=\\\"page-number '+(page===i+1?'active':'')+'\\\">'+(i+1)+'</button>').join('');[...document.querySelectorAll('#postPagination button')].forEach((b,i)=>b.onclick=()=>{page=i+1;draw()});};draw()});");}
