    private static String adminPage(){return layout("관리자 | CINEHUB","<div class='container admin-dashboard'><section class='hero admin-hero'><span class='muted'>ADMIN</span><h1>관리자 대시보드</h1><div id='stats'>통계를 불러오는 중입니다.</div><p><a class='btn-main' href='/admin/logs'>관리 로그 보기</a></p></section><h2>회원 관리</h2><div class='admin-search'><input id='adminUserSearch' oninput='filterAdminUsers()' placeholder='닉네임 또는 아이디 검색'><button onclick='filterAdminUsers()'>검색</button></div><div id='users'></div><h2>게시글 관리</h2><p class='muted'>한 페이지에 5개씩 표시됩니다. 숨김 처리한 글은 일반 게시글 목록에서 즉시 제외됩니다.</p><div class='admin-search'><input id='adminPostSearch' oninput='loadAdminPostsCompact()' placeholder='게시글 제목 또는 작성자 검색'><button onclick='loadAdminPostsCompact()'>검색</button></div><nav class='pagination pagination-top' id='adminPostPaginationTop'></nav><div id='adminPosts'></div><nav class='pagination' id='adminPostPagination'></nav><h2>신고 관리</h2><div id='reports'></div></div>","function filterAdminUsers(){var q=document.getElementById('adminUserSearch').value.toLowerCase();Array.prototype.forEach.call(document.querySelectorAll('#users .post-card'),function(x){x.style.display=x.textContent.toLowerCase().indexOf(q)>=0?'block':'none';});}function loadAdminPostsCompact(){fetch('/api/posts').then(function(r){return r.json();}).then(function(d){var a=d.posts||[],q=document.getElementById('adminPostSearch').value.toLowerCase(),shown=q?a.filter(function(p){return (p.title+' '+p.author).toLowerCase().indexOf(q)>=0;}):a,page=1,draw=function(){var pages=Math.max(1,Math.ceil(shown.length/5));document.getElementById('adminPosts').innerHTML=shown.slice((page-1)*5,page*5).map(function(p){return '<div class=\"post-card admin-post-row\"><b>'+safe(p.title)+'</b><span>'+safe(p.author)+'</span><a class=\"btn-main\" href=\"/post/'+p.id+'\">보기</a><button class=\"btn-main\" onclick=\"hideAdminPost('+p.id+')\">숨김</button></div>';}).join('')||'<p class=\"muted\">검색 결과가 없습니다.</p>';var controls=Array.from({length:pages},function(_,i){return '<button class=\"page-number '+(page===i+1?'active':'')+'\">'+(i+1)+'</button>';}).join('');document.getElementById('adminPostPaginationTop').innerHTML=controls;document.getElementById('adminPostPagination').innerHTML=controls;Array.prototype.forEach.call(document.querySelectorAll('#adminPostPaginationTop button,#adminPostPagination button'),function(b,i){b.onclick=function(){page=i%pages+1;draw();};});};draw();});}function hideAdminPost(id){if(!confirm('이 게시글을 숨길까요?'))return;fetch('/api/admin/posts/'+id+'/hide',{method:'PUT'}).then(function(r){if(r.ok){loadAdminPostsCompact();loadAdmin();}});}loadAdmin();loadAdminPostsCompact();loadReports();");}
