        +"function sessionNav(){fetch('/api/me').then(function(r){return r.ok?r.json():null;}).then(function(u){if(!u)return;document.getElementById('navLogin').style.display='none';document.getElementById('navRegister').style.display='none';document.getElementById('navUser').style.display='inline-block';document.getElementById('navLogout').style.display='inline-block';document.getElementById('navNotifications').style.display='list-item';document.getElementById('navMyPage').textContent=u.nickname+'님';if(u.role==='ADMIN')document.getElementById('navAdmin').style.display='list-item';});}"
        +"function loadAdmin(){fetch('/api/admin/stats').then(function(r){return r.json();}).then(function(s){document.getElementById('stats').textContent='게시글 '+s.posts+' · 댓글 '+s.comments+' · 회원 '+s.users+' · 미처리 신고 '+s.pendingReports;return fetch('/api/admin/users');}).then(function(r){return r.json();}).then(function(d){document.getElementById('users').innerHTML=(d.users||[]).map(function(u){var action=u.status==='SUSPENDED'?'ACTIVE':'SUSPENDED';return '<div class=\\\"post-card\\\"><b>'+safe(u.nickname)+'</b> ('+safe(u.loginId)+') · '+safe(u.status)+' <button class=\\\"btn-main\\\" onclick=\\\"setUserStatus('+u.id+',\\\''+action+'\\\')\\\">'+(action==='SUSPENDED'?'정지':'정지 해제')+'</button></div>';}).join('');}).catch(function(){location.href='/';});}function setUserStatus(id,status){fetch('/api/admin/users/'+id+'/status',{method:'PUT',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:'status='+status}).then(function(){loadAdmin();});}function loadAdminPosts(){fetch('/api/posts').then(function(r){return r.json();}).then(function(d){document.getElementById('adminPosts').innerHTML=(d.posts||[]).map(function(p){return '<div class=\\\"post-card\\\"><b>'+safe(p.title)+'</b> · '+safe(p.author)+' <a class=\\\"btn-main\\\" href=\\\"/post/'+p.id+'\\\">보기</a> <button class=\\\"btn-main\\\" onclick=\\\"hidePost('+p.id+')\\\">숨김</button></div>';}).join('')||'<p class=\\\"muted\\\">표시할 게시글이 없습니다.</p>';});}function hidePost(id){if(!confirm('이 게시글을 숨길까요?'))return;fetch('/api/admin/posts/'+id+'/hide',{method:'PUT'}).then(function(r){if(r.ok){loadAdminPosts();loadAdmin();}});}"
        +"function loadReports(){fetch('/api/admin/reports').then(function(r){return r.json();}).then(function(d){document.getElementById('reports').innerHTML=(d.reports||[]).map(function(x){return '<div class=\\\"post-card\\\"><b>'+safe(x.type)+' #'+x.targetId+'</b> · '+safe(x.reason)+' · '+safe(x.status)+' <button class=\\\"btn-main\\\" onclick=\\\"resolveReport('+x.id+',\\\'RESOLVED\\\')\\\">처리</button> <button class=\\\"btn-main\\\" onclick=\\\"resolveReport('+x.id+',\\\'REJECTED\\\')\\\">반려</button></div>';}).join('')||'<p class=\\\"muted\\\">신고가 없습니다.</p>';});}function resolveReport(id,status){fetch('/api/admin/reports/'+id,{method:'PUT',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:'status='+status}).then(function(){loadReports();loadAdmin();});}"
        +"function bindBoardForm(){document.getElementById('boardForm').addEventListener('submit',function(e){e.preventDefault();fetch('/api/boards',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams(new FormData(e.target))}).then(function(r){if(r.ok){e.target.reset();loadBoards();}else document.getElementById('message').textContent='추가하지 못했습니다.';});});}function loadBoards(){fetch('/api/boards').then(function(r){return r.json();}).then(function(d){window.currentBoards=d.boards||[];document.getElementById('boards').innerHTML=window.currentBoards.map(function(b){return '<div class=\\\"post-card\\\"><b>'+safe(b.name)+'</b> · '+safe(b.description)+' <button class=\\\"btn-main\\\" onclick=\\\"editBoard('+b.id+')\\\">수정</button> <button class=\\\"btn-main\\\" onclick=\\\"removeBoard('+b.id+')\\\">삭제</button></div>';}).join('');});}function editBoard(id){var b=(window.currentBoards||[]).filter(function(x){return x.id===id;})[0];if(!b)return;var name=prompt('게시판 이름',b.name);if(name===null||!name.trim())return;var description=prompt('게시판 설명',b.description||'');if(description===null)return;fetch('/api/boards/'+id,{method:'PUT',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams({name:name.trim(),description:description,sortOrder:99})}).then(function(r){if(r.ok)loadBoards();});}function removeBoard(id){if(!confirm('게시판을 삭제할까요?'))return;fetch('/api/boards/'+id,{method:'DELETE'}).then(function(r){if(r.ok)loadBoards();});}"
        +"function loadPostDetail(id){Promise.all([fetch('/api/posts/'+id).then(function(r){return r.json();}),fetch('/api/me').then(function(r){return r.ok?r.json():null;})]).then(function(a){var p=a[0],u=a[1],root=document.getElementById('post');root.innerHTML='<p class=\"muted\"></p><h1></h1><p class=\"post-stats\"></p><hr><div class=\"post-body\"></div><div id=\"postActions\"></div>';root.querySelector('p.muted').textContent=p.author+' · '+p.createdAt;root.querySelector('h1').textContent=p.title;root.querySelector('.post-body').textContent=p.content;var stats=root.querySelector('.post-stats');stats.textContent='조회 '+p.views+' · 좋아요 ';var count=document.createElement('b');count.id='likeCount';count.textContent=p.likes;stats.appendChild(count);if(u){var like=document.createElement('button');like.className='btn-main post-like-button';like.id='likeButton';like.textContent=p.liked?'♥ 좋아요 취소':'♡ 좋아요';like.onclick=function(){togglePostLike(id);};stats.appendChild(document.createTextNode(' '));stats.appendChild(like);}if(u&&(u.id===p.authorId||u.role==='ADMIN')){var actions=document.getElementById('postActions');actions.innerHTML='<p><a class=\"btn-main\" href=\"/edit-post/'+id+'\">수정</a> <button class=\"btn-main\" id=\"deletePostButton\">삭제</button></p>';document.getElementById('deletePostButton').onclick=function(){deletePost(id);};}}).catch(function(){document.getElementById('post').textContent='게시글을 찾을 수 없습니다.';});}function togglePostLike(id){fetch('/api/posts/'+id+'/like',{method:'POST'}).then(function(r){if(r.status===401){location.href='/login';return null;}return r.json();}).then(function(d){if(!d)return;document.getElementById('likeCount').textContent=d.likes;document.getElementById('likeButton').textContent=d.liked?'♥ 좋아요 취소':'♡ 좋아요';});}function logoutNow(){fetch('/api/auth/logout',{method:'POST'}).then(function(){location.href='/';});}function withdrawAccount(){if(!confirm('회원 탈퇴 후에는 같은 계정으로 다시 로그인할 수 없습니다. 계속할까요?'))return;fetch('/api/me',{method:'DELETE'}).then(function(r){if(r.ok){alert('회원 탈퇴가 완료되었습니다.');location.href='/';return;}return r.json();}).then(function(d){if(d)alert(d.error||'회원 탈퇴를 처리하지 못했습니다.');});}sessionNav();";
    private User session(HttpExchange e){String token=cookie(e);User cached=sessions.get(token);if(cached==null)throw new IllegalStateException("login required");User current=users.findByUserId(cached.getUserId());if(current==null||!"ACTIVE".equals(current.getStatus())){sessions.remove(token);csrfTokens.remove(token);throw new IllegalStateException("login required");}sessions.put(token,current);return current;} private boolean needsCsrf(HttpExchange e){String method=e.getRequestMethod();return ("POST".equals(method)||"PUT".equals(method)||"DELETE".equals(method))&&!cookie(e).isBlank()&&!"/api/auth/login".equals(e.getRequestURI().getPath())&&!"/api/auth/register".equals(e.getRequestURI().getPath());} private boolean csrfValid(HttpExchange e){String expected=csrfTokens.get(cookie(e));String actual=e.getRequestHeaders().getFirst("X-CSRF-Token");return expected!=null&&expected.equals(actual);} private static String cookie(HttpExchange e){String raw=e.getRequestHeaders().getFirst("Cookie");if(raw!=null)for(String part:raw.split(";")){String[] p=part.trim().split("=",2);if(p.length==2&&"CINEHUB_SESSION".equals(p[0]))return p[1];}return"";}
    private static Map<String,String> form(HttpExchange e)throws IOException{String body=new String(e.getRequestBody().readAllBytes(),StandardCharsets.UTF_8);Map<String,String> out=new HashMap<>();for(String item:body.split("&")){int n=item.indexOf('=');if(n>=0)out.put(URLDecoder.decode(item.substring(0,n),StandardCharsets.UTF_8),URLDecoder.decode(item.substring(n+1),StandardCharsets.UTF_8));}return out;} private static String req(Map<String,String> f,String key){String value=f.get(key);if(value==null||value.isBlank())throw new IllegalArgumentException(key+" is required");return value;} private static long id(String path){for(String part:path.split("/"))if(part.matches("\\d+"))return Long.parseLong(part);throw new IllegalArgumentException("id required");}
    private static String query(HttpExchange e,String key){String raw=e.getRequestURI().getRawQuery();if(raw!=null)for(String pair:raw.split("&")){String[] p=pair.split("=",2);if(p.length==2&&key.equals(p[0]))return URLDecoder.decode(p[1],StandardCharsets.UTF_8);}return "";}private static boolean get(HttpExchange e){return"GET".equals(e.getRequestMethod());}private static boolean post(HttpExchange e){return"POST".equals(e.getRequestMethod());}private static boolean put(HttpExchange e){return"PUT".equals(e.getRequestMethod());}private static boolean delete(HttpExchange e){return"DELETE".equals(e.getRequestMethod());}private static String esc(String s){return(s==null?"":s).replace("\\","\\\\").replace("\"","\\\"").replace("\n"," ").replace("\r"," ");}private static void json(HttpExchange e,int code,String body)throws IOException{send(e,code,"application/json; charset=utf-8",body);}private static void html(HttpExchange e,int code,String body)throws IOException{send(e,code,"text/html; charset=utf-8",addPostListStats(body));}private static String addPostListStats(String body){String script="<script>(function(){var timer;function fill(){fetch('/api/posts').then(function(r){return r.json();}).then(function(d){var by={};(d.posts||[]).forEach(function(p){by[p.id]=p;});document.querySelectorAll('a.post-card:not([data-list-stats])').forEach(function(card){var m=(card.getAttribute('href')||'').match(/\\/post\\/(\\d+)/);var p=m&&by[m[1]];if(!p)return;var s=document.createElement('small');s.className='muted post-list-stats';s.textContent='조회 '+p.views+' · 좋아요 '+p.likes;card.appendChild(s);card.setAttribute('data-list-stats','1');});});}function schedule(){clearTimeout(timer);timer=setTimeout(fill,40);}new MutationObserver(schedule).observe(document.documentElement,{childList:true,subtree:true});schedule();})();</script>";return body.replace("</body>",script+"</body>");}private static void redirect(HttpExchange e,String location)throws IOException{e.getResponseHeaders().set("Location",location);e.sendResponseHeaders(302,-1);e.close();}private static void send(HttpExchange e,int code,String type,String body)throws IOException{byte[] b=body.getBytes(StandardCharsets.UTF_8);e.getResponseHeaders().set("Content-Type",type);e.getResponseHeaders().set("Cache-Control","no-store");e.sendResponseHeaders(code,b.length);e.getResponseBody().write(b);e.close();}
